INSERT INTO public.permissions(code,description) VALUES ('hotel.sms.view','Voir l’historique SMS Hôtel'),('hotel.sms.send','Envoyer des SMS transactionnels Hôtel'),('hotel.sms.settings','Configurer les automatisations SMS Hôtel') ON CONFLICT(code) DO UPDATE SET description=EXCLUDED.description;
CREATE TABLE public.hotel_sms_settings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL UNIQUE REFERENCES public.tenants(id) ON DELETE CASCADE,automatic_sending_enabled boolean NOT NULL DEFAULT false,arrival_reminder_enabled boolean NOT NULL DEFAULT false,arrival_reminder_hours integer NOT NULL DEFAULT 24 CHECK(arrival_reminder_hours BETWEEN 1 AND 168),departure_reminder_enabled boolean NOT NULL DEFAULT false,departure_reminder_hours integer NOT NULL DEFAULT 4 CHECK(departure_reminder_hours BETWEEN 1 AND 72),balance_reminder_enabled boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now(),updated_by uuid REFERENCES auth.users(id));
CREATE TABLE public.hotel_sms_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES public.tenants(id) ON DELETE RESTRICT,reservation_id uuid NOT NULL,guest_id uuid NOT NULL,phone text NOT NULL,message_type text NOT NULL CHECK(message_type IN ('confirmation','arrival_reminder','departure_reminder','balance_reminder','cancellation','thanks')),message text NOT NULL CHECK(length(message) BETWEEN 1 AND 918),provider text NOT NULL,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','sent','failed')),provider_message_id text,error_message text,sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES auth.users(id),FOREIGN KEY(reservation_id,tenant_id) REFERENCES public.hotel_reservations(id,tenant_id) ON DELETE RESTRICT,FOREIGN KEY(guest_id,tenant_id) REFERENCES public.hotel_guests(id,tenant_id) ON DELETE RESTRICT);
CREATE INDEX hotel_sms_logs_tenant_reservation_created_idx ON public.hotel_sms_logs(tenant_id,reservation_id,created_at DESC);
ALTER TABLE public.hotel_sms_logs ENABLE ROW LEVEL SECURITY; ALTER TABLE public.hotel_sms_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY hotel_sms_logs_select ON public.hotel_sms_logs FOR SELECT TO authenticated USING (tenant_id=public.hotel_tenant_id() AND public.hotel_module_enabled('hotel_reservations') AND public.has_permission('hotel.sms.view'));
CREATE POLICY hotel_sms_settings_select ON public.hotel_sms_settings FOR SELECT TO authenticated USING (tenant_id=public.hotel_tenant_id() AND public.has_permission('hotel.settings.view'));
CREATE POLICY hotel_sms_settings_write ON public.hotel_sms_settings FOR ALL TO authenticated USING (tenant_id=public.hotel_tenant_id() AND public.has_permission('hotel.sms.settings')) WITH CHECK (tenant_id=public.hotel_tenant_id() AND public.has_permission('hotel.sms.settings') AND updated_by=auth.uid());
REVOKE ALL ON public.hotel_sms_logs,public.hotel_sms_settings FROM anon; GRANT SELECT ON public.hotel_sms_logs TO authenticated; GRANT SELECT,INSERT,UPDATE ON public.hotel_sms_settings TO authenticated; GRANT ALL ON public.hotel_sms_logs,public.hotel_sms_settings TO service_role;
CREATE OR REPLACE FUNCTION public.prevent_hotel_sms_log_mutation() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF TG_OP='DELETE' THEN RAISE EXCEPTION 'L’historique SMS ne peut pas être supprimé'; END IF; IF OLD.tenant_id<>NEW.tenant_id OR OLD.reservation_id<>NEW.reservation_id OR OLD.guest_id<>NEW.guest_id OR OLD.phone<>NEW.phone OR OLD.message_type<>NEW.message_type OR OLD.message<>NEW.message OR OLD.provider<>NEW.provider OR OLD.created_by<>NEW.created_by OR OLD.created_at<>NEW.created_at THEN RAISE EXCEPTION 'Le contenu de l’historique SMS est immuable'; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_hotel_sms_logs BEFORE UPDATE OR DELETE ON public.hotel_sms_logs FOR EACH ROW EXECUTE FUNCTION public.prevent_hotel_sms_log_mutation();
CREATE OR REPLACE FUNCTION public.prepare_hotel_sms(target_reservation_id uuid,sms_type text,sms_message text,sms_provider text) RETURNS TABLE(log_id uuid,phone text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid:=public.hotel_tenant_id(); rid uuid; gid uuid; guest_phone text; new_id uuid; BEGIN IF tid IS NULL OR NOT public.hotel_module_enabled('hotel_reservations') OR NOT public.has_permission('hotel.sms.send') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Permission d’envoi SMS requise'; END IF; IF sms_type NOT IN ('confirmation','arrival_reminder','departure_reminder','balance_reminder','cancellation','thanks') OR length(btrim(sms_message)) NOT BETWEEN 1 AND 918 THEN RAISE EXCEPTION 'Message SMS invalide'; END IF; SELECT r.id,r.guest_id,g.phone INTO rid,gid,guest_phone FROM public.hotel_reservations r JOIN public.hotel_guests g ON g.id=r.guest_id AND g.tenant_id=r.tenant_id WHERE r.id=target_reservation_id AND r.tenant_id=tid; IF rid IS NULL OR guest_phone IS NULL THEN RAISE EXCEPTION 'Réservation ou téléphone introuvable'; END IF; IF EXISTS(SELECT 1 FROM public.hotel_sms_logs WHERE tenant_id=tid AND reservation_id=rid AND created_by=auth.uid() AND created_at>now()-interval '30 seconds') THEN RAISE EXCEPTION 'Veuillez patienter avant un nouvel envoi'; END IF; IF (SELECT count(*) FROM public.hotel_sms_logs WHERE tenant_id=tid AND created_by=auth.uid() AND created_at>now()-interval '1 hour')>=30 OR (SELECT count(*) FROM public.hotel_sms_logs WHERE tenant_id=tid AND reservation_id=rid AND created_at>now()-interval '1 day')>=10 THEN RAISE EXCEPTION 'Limite d’envoi atteinte'; END IF; INSERT INTO public.hotel_sms_logs(tenant_id,reservation_id,guest_id,phone,message_type,message,provider,created_by) VALUES(tid,rid,gid,guest_phone,sms_type,btrim(sms_message),sms_provider,auth.uid()) RETURNING id INTO new_id; RETURN QUERY SELECT new_id,guest_phone; END $$;
CREATE OR REPLACE FUNCTION public.complete_hotel_sms(target_log_id uuid,final_status text,external_id text,failure_message text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF final_status NOT IN ('sent','pending','failed') THEN RAISE EXCEPTION 'Statut SMS invalide'; END IF; UPDATE public.hotel_sms_logs SET status=final_status,provider_message_id=external_id,error_message=failure_message,sent_at=CASE WHEN final_status='sent' THEN now() ELSE NULL END WHERE id=target_log_id AND tenant_id=public.hotel_tenant_id() AND created_by=auth.uid() AND status='pending'; IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='Journal SMS inaccessible'; END IF; END $$;
REVOKE ALL ON FUNCTION public.prepare_hotel_sms(uuid,text,text,text),public.complete_hotel_sms(uuid,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.prepare_hotel_sms(uuid,text,text,text),public.complete_hotel_sms(uuid,text,text,text) TO authenticated;
INSERT INTO public.role_permissions(role_id,permission_id) SELECT r.id,p.id FROM public.roles r CROSS JOIN public.permissions p WHERE r.name='Administrateur' AND p.code IN ('hotel.sms.view','hotel.sms.send','hotel.sms.settings') ON CONFLICT DO NOTHING;
